import{_ as e,c as l,o as i,ag as t}from"./chunks/framework.B1jFR3yW.js";const _=JSON.parse('{"title":"007 朴素贝叶斯","description":"","frontmatter":{},"headers":[],"relativePath":"python/机器学习/007朴素贝叶斯.md","filePath":"python/机器学习/007朴素贝叶斯.md"}'),r={name:"python/机器学习/007朴素贝叶斯.md"};function o(h,a,n,d,s,c){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="_007-朴素贝叶斯" tabindex="-1">007 朴素贝叶斯 <a class="header-anchor" href="#_007-朴素贝叶斯" aria-label="Permalink to &quot;007 朴素贝叶斯&quot;">​</a></h1><h2 id="朴素贝叶斯是什么" tabindex="-1">朴素贝叶斯是什么 <a class="header-anchor" href="#朴素贝叶斯是什么" aria-label="Permalink to &quot;朴素贝叶斯是什么&quot;">​</a></h2><p>朴素贝叶斯是一类基于贝叶斯定理的分类算法。</p><p>它之所以叫“朴素”，是因为它做了一个很强的假设：</p><p>各个特征之间条件独立。</p><p>虽然这个假设在现实里经常不完全成立，但它在很多任务中仍然非常实用。</p><h2 id="适合什么任务" tabindex="-1">适合什么任务 <a class="header-anchor" href="#适合什么任务" aria-label="Permalink to &quot;适合什么任务&quot;">​</a></h2><ul><li>文本分类</li><li>垃圾邮件识别</li><li>情感分析</li><li>简单评论分类</li></ul><h2 id="核心思想" tabindex="-1">核心思想 <a class="header-anchor" href="#核心思想" aria-label="Permalink to &quot;核心思想&quot;">​</a></h2><p>已知特征条件下，计算样本属于各类别的概率，最后选概率最大的类别。</p><h2 id="朴素贝叶斯的优缺点" tabindex="-1">朴素贝叶斯的优缺点 <a class="header-anchor" href="#朴素贝叶斯的优缺点" aria-label="Permalink to &quot;朴素贝叶斯的优缺点&quot;">​</a></h2><h3 id="优点" tabindex="-1">优点 <a class="header-anchor" href="#优点" aria-label="Permalink to &quot;优点&quot;">​</a></h3><ul><li>训练速度快</li><li>对文本任务友好</li><li>小数据场景也常能工作</li></ul><h3 id="缺点" tabindex="-1">缺点 <a class="header-anchor" href="#缺点" aria-label="Permalink to &quot;缺点&quot;">​</a></h3><ul><li>独立性假设较强</li><li>对复杂特征关系表达有限</li></ul><h2 id="为什么它常见于文本任务" tabindex="-1">为什么它常见于文本任务 <a class="header-anchor" href="#为什么它常见于文本任务" aria-label="Permalink to &quot;为什么它常见于文本任务&quot;">​</a></h2><p>因为在词袋模型、词频统计这类表示方法下，朴素贝叶斯实现简单，速度快，而且往往能拿到不错的基线效果。</p><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><p>学习朴素贝叶斯时，最重要的是记住：</p><ul><li>它是分类模型</li><li>它依赖概率思想</li><li>它做了“特征条件独立”的朴素假设</li><li>它在文本分类里非常常见</li></ul>',20)])])}const p=e(r,[["render",o]]);export{_ as __pageData,p as default};
